import osimport socketimport sysok = Truefn = input('Enter file name: ')if fn.find('/') < 0:         fn = "/home/eric/Downloads/" + fn  lc = 0 # line count#read file into res list belowres = ''try:    fo = open(fn,"rb")except ValueError as e:    ok = False    print('Unable to open to file {}.  Error : {}'.format(fn,e))    print("Exiting")print('filed {} opened mode: {} '.format(fo.name,fo.mode))if ok:    try:        br=fo.read()        print('Read sucessful type(br) = {}'.format(type(br)))    except ValueError as e:        print('File read error: {}'.format(e))fo.close()res = br.decode()if res[0] != chr(11):    res = chr(11) + resif res.find(chr(13)) == -1:    nr = res.replace('\n','\r')    #nr += 'OBX|999|TX|00000^Format Utility^PCV4|1|mllp_wrapper called and added this OBX segemrnt\r'else:    nr = resif nr.find(chr(28)) == -1:    cma = chr(28) + '\r' # close message ascii    if nr[-1] != 13:        cma = '\r' + cma    nr += cmabr = nr.encode()ten = br.find(10)cr = br.find(13)emm = br.find(28)print('ten = {}  cr = {}  eem = {}'.format(ten, cr, emm))print('type(br) = {}'.format(type(br)))ba = bytearray(br)print('type(ba) = {}'.format(type(ba)))# no real need to save the file back since I wond up sending it w/ code belowwant2save = Falseif want2save:    fo = open(fn,'wb')    try:        fo.write(ba)        print('write ba succeeded for file {}'.format(fn))        fo.close    except ValueError as e:        print('Write attempt failed: {}'.format(e))        fo.close()ip_n_port = ('192.168.15.100',6661)print('br:\n{}'.format(br))sr = br.decode()# print('ord(sr[0]) = {}'.format(ord(sr[0])))# print('sr:\n{}'.format(sr))o_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)try:    o_sock.connect(ip_n_port)    print('connect called for {}'.format(ip_n_port))except ValueError as e:    print('Error on connect attempt: {}'.format(e))print('Attempting to send message')try:    o_sock.sendall(br)except ValueError as e:    print('write Error encountered:\n{}'.format(e))eomd = Falseack = ''fullAck = ''while fullAck.find(chr(28)) == -1:    try:        ack = o_sock.recv(256)        fullAck = fullAck + ack.decode()        print('fullAck = {}'.format(fullAck))    except ValueError as e:        print('recieve error:\n{}'.format(e))o_sock.close()print('reached end without crash, check mirth for message.')            